 / 1.5L PET Bottle","ur":"Polar 500 ملی لیٹر / 1.5 لیٹر پیٹ بوتل"},{"en":"Safa 500ml / 1.5L PET Bottle","ur":"Safa 500 ملی لیٹر / 1.5 لیٹر پیٹ بوتل"},{"en":"Murree Sparkletts 500ml / 1.5L PET Bottle","ur":"Murree Sparkletts 500 ملی لیٹر / 1.5 لیٹر پیٹ بوتل"}]$json$::jsonb;
  v_it  jsonb;
  v_n   int := 0;
begin
  for v_it in select * from jsonb_array_elements(v_map) loop
    update products
       set name_ur = v_it->>'ur'
     where name_en = v_it->>'en'
       and coalesce(btrim(name_ur), '') = '';
    if found then v_n := v_n + 1; end if;
  end loop;
  raise notice 'Urdu names filled: %', v_n;
end
